mapper.update:
UPDATE TBL_AR_RECEIVABLE
DOCUMENT_NO = #{documentNo}, CUSTOMER_ID = #{customerId}, BUSINESS_TYPE = #{businessType}, RECEIVABLE_AMOUNT = #{receivableAmount}, RECEIVED_AMOUNT = #{receivedAmount}, REMAINING_AMOUNT = #{remainingAmount}, DOCUMENT_STATUS = #{documentStatus}, DUE_DATE = #{dueDate}, CURRENCY = #{currency}, EXCHANGE_RATE = #{exchangeRate}, REMARKS = #{remarks}, AUDIT_TIME = #{auditTime}, AUDITOR_ID = #{auditorId}, AUDIT_COMMENTS = #{auditComments}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy}, IS_DELETED = #{isDeleted},
WHERE RECEIVABLE_ID = #{receivableId}

mapper.select:
SELECT r.RECEIVABLE_ID, r.DOCUMENT_NO, r.CUSTOMER_ID, r.BUSINESS_TYPE, r.RECEIVABLE_AMOUNT,
       r.RECEIVED_AMOUNT, r.REMAINING_AMOUNT, r.DOCUMENT_STATUS, r.DUE_DATE, r.CURRENCY,
       r.EXCHANGE_RATE, r.REMARKS, r.AUDIT_TIME, r.AUDITOR_ID, r.AUDIT_COMMENTS,
       r.TENANT_ID, r.ORG_ID, r.BOOK_ID, r.CREATE_TIME, r.CREATE_BY, r.UPDATE_TIME, r.UPDATE_BY, r.IS_DELETED,
       c.CUSTOMER_NAME AS customerName
FROM TBL_AR_RECEIVABLE r
LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
WHERE r.IS_DELETED = 0

    AND r.TENANT_ID = #{param.tenantId}


    AND r.DOCUMENT_NO LIKE '%' || #{param.documentNo} || '%'


    AND r.CUSTOMER_ID = #{param.customerId}


    AND r.BUSINESS_TYPE = #{param.businessType}


    AND r.DOCUMENT_STATUS = #{param.documentStatus}


    AND r.DUE_DATE >= #{param.dueDateStart}


    AND r.DUE_DATE <= #{param.dueDateEnd}

ORDER BY r.CREATE_TIME DESC

SELECT * FROM ( SELECT r.CUSTOMER_ID AS customerId, c.CUSTOMER_NAME AS customerName, SUM(r.REMAINING_AMOUNT) AS receivableAmount, ROUND(SUM(r.REMAINING_AMOUNT) * 100 / (SELECT NVL(SUM(REMAINING_AMOUNT), 1) FROM TBL_AR_RECEIVABLE WHERE IS_DELETED = 0 AND DOCUMENT_STATUS = 2 AND TENANT_ID = #{tenantId}), 2) AS percentage FROM TBL_AR_RECEIVABLE r LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 WHERE r.IS_DELETED = 0 AND r.DOCUMENT_STATUS = 2
AND r.TENANT_ID = #{tenantId}
GROUP BY r.CUSTOMER_ID, c.CUSTOMER_NAME ORDER BY SUM(r.REMAINING_AMOUNT) DESC ) WHERE ROWNUM <= #{topN}

SELECT agingRange, amount, documentCount, sortOrder FROM ( SELECT CASE WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 0 THEN '未到期' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 30 THEN '1-30天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 60 THEN '31-60天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 90 THEN '61-90天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 180 THEN '91-180天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 365 THEN '181-365天' ELSE '1年以上' END AS agingRange, CASE WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 0 THEN 1 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 30 THEN 2 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 60 THEN 3 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 90 THEN 4 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 180 THEN 5 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 365 THEN 6 ELSE 7 END AS sortOrder, SUM(REMAINING_AMOUNT) AS amount, COUNT(*) AS documentCount FROM TBL_AR_RECEIVABLE WHERE IS_DELETED = 0 AND DOCUMENT_STATUS = 2 AND REMAINING_AMOUNT > 0
AND TENANT_ID = #{tenantId}
GROUP BY CASE WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 0 THEN '未到期' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 30 THEN '1-30天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 60 THEN '31-60天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 90 THEN '61-90天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 180 THEN '91-180天' WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 365 THEN '181-365天' ELSE '1年以上' END, CASE WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 0 THEN 1 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 30 THEN 2 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 60 THEN 3 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 90 THEN 4 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 180 THEN 5 WHEN TRUNC(#{analysisDate}) - DUE_DATE <= 365 THEN 6 ELSE 7 END ) t ORDER BY sortOrder

SELECT BUSINESS_TYPE AS businessType, CASE BUSINESS_TYPE WHEN 1 THEN '销售收入' WHEN 2 THEN '服务收入' WHEN 3 THEN '租赁收入' WHEN 4 THEN '其他收入' ELSE '未知' END AS businessTypeName, SUM(REMAINING_AMOUNT) AS amount, ROUND(SUM(REMAINING_AMOUNT) * 100 / (SELECT NVL(SUM(REMAINING_AMOUNT), 1) FROM TBL_AR_RECEIVABLE WHERE IS_DELETED = 0 AND DOCUMENT_STATUS = 2 AND TENANT_ID = #{tenantId}), 2) AS percentage FROM TBL_AR_RECEIVABLE WHERE IS_DELETED = 0 AND DOCUMENT_STATUS = 2
AND TENANT_ID = #{tenantId}
GROUP BY BUSINESS_TYPE ORDER BY SUM(REMAINING_AMOUNT) DESC

SELECT * FROM ( SELECT r.CUSTOMER_ID AS customerId, c.CUSTOMER_NAME AS customerName, SUM(r.REMAINING_AMOUNT) AS receivableBalance, SUM(CASE WHEN r.DUE_DATE < TRUNC(SYSDATE) THEN r.REMAINING_AMOUNT ELSE 0 END) AS overdueAmount, NVL(ROUND(AVG( CASE WHEN r.DUE_DATE < TRUNC(SYSDATE) THEN TRUNC(SYSDATE) - r.DUE_DATE ELSE 0 END ), 0), 0) AS averageAgingDays, c.CREDIT_LEVEL AS creditLevel, MAX(rec.RECEIPT_DATE) AS lastPaymentDate, ROUND(NVL(SUM(r.RECEIVED_AMOUNT), 0) * 100 / NULLIF(SUM(r.RECEIVABLE_AMOUNT), 0), 1) AS collectionRate FROM TBL_AR_RECEIVABLE r LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 LEFT JOIN TBL_AR_RECEIPT rec ON r.CUSTOMER_ID = rec.CUSTOMER_ID AND rec.IS_DELETED = 0 AND rec.RECEIPT_STATUS = 1 WHERE r.IS_DELETED = 0 AND r.DOCUMENT_STATUS = 2
AND r.TENANT_ID = #{tenantId}
AND r.CREATE_TIME >= #{startDate}
AND r.CREATE_TIME <= #{endDate}
GROUP BY r.CUSTOMER_ID, c.CUSTOMER_NAME, c.CREDIT_LEVEL ORDER BY
SUM(CASE WHEN r.DUE_DATE < TRUNC(SYSDATE) THEN r.REMAINING_AMOUNT ELSE 0 END) DESC AVG(CASE WHEN r.DUE_DATE < TRUNC(SYSDATE) THEN TRUNC(SYSDATE) - r.DUE_DATE ELSE 0 END) DESC SUM(r.REMAINING_AMOUNT) DESC
) WHERE ROWNUM <= #{topN}

SELECT NVL(ROUND(AVG(rec.RECEIPT_DATE - r.CREATE_TIME), 0), 0) AS averageCollectionCycle, NVL(ROUND(SUM(r.RECEIVABLE_AMOUNT) / NULLIF(AVG(r.REMAINING_AMOUNT), 0), 2), 0) AS receivableTurnover, NVL(ROUND(SUM(CASE WHEN r.REMAINING_AMOUNT > 0 AND r.DUE_DATE < TRUNC(SYSDATE) - 365 THEN r.REMAINING_AMOUNT ELSE 0 END) * 100 / NULLIF(SUM(r.RECEIVABLE_AMOUNT), 0), 2), 0) AS badDebtRate FROM TBL_AR_RECEIVABLE r LEFT JOIN TBL_AR_RECEIPT rec ON r.CUSTOMER_ID = rec.CUSTOMER_ID AND rec.IS_DELETED = 0 AND rec.RECEIPT_STATUS = 1 WHERE r.IS_DELETED = 0 AND r.DOCUMENT_STATUS = 2
AND r.TENANT_ID = #{tenantId}
AND r.CREATE_TIME >= #{startDate}
AND r.CREATE_TIME <= #{endDate}

SELECT TO_CHAR(r.CREATE_TIME, 'YYYY-MM') AS month, SUM(r.RECEIVABLE_AMOUNT) AS receivableAmount, SUM(r.RECEIVED_AMOUNT) AS collectedAmount, ROUND(NVL(SUM(r.RECEIVED_AMOUNT), 0) * 100 / NULLIF(SUM(r.RECEIVABLE_AMOUNT), 0), 1) AS collectionRate, NVL(ROUND(AVG(rec.RECEIPT_DATE - r.CREATE_TIME), 0), 0) AS averageCycle, NVL(ROUND(SUM(r.RECEIVABLE_AMOUNT) / NULLIF(AVG(r.REMAINING_AMOUNT), 0), 2), 0) AS turnoverRate, ROUND(NVL(SUM(CASE WHEN r.DUE_DATE < TRUNC(SYSDATE) THEN r.REMAINING_AMOUNT ELSE 0 END), 0) * 100 / NULLIF(SUM(r.RECEIVABLE_AMOUNT), 0), 1) AS overdueRate FROM TBL_AR_RECEIVABLE r LEFT JOIN TBL_AR_RECEIPT rec ON r.CUSTOMER_ID = rec.CUSTOMER_ID AND rec.IS_DELETED = 0 AND rec.RECEIPT_STATUS = 1 WHERE r.IS_DELETED = 0 AND r.DOCUMENT_STATUS = 2
AND r.TENANT_ID = #{tenantId}
AND r.CREATE_TIME >= #{startDate}
AND r.CREATE_TIME <= #{endDate}
GROUP BY TO_CHAR(r.CREATE_TIME, 'YYYY-MM') ORDER BY TO_CHAR(r.CREATE_TIME, 'YYYY-MM')
